def maximumGood(statements: list[list[int]]) -> int:
    n = len(statements)
    ans = 0
    for mask in range(1 << n):
        valid = True
        for i in range(n):
            if mask & (1 << i):
                for j in range(n):
                    st = statements[i][j]
                    if st == 0 and (mask & (1 << j)):
                        valid = False
                        break
                    if st == 1 and not (mask & (1 << j)):
                        valid = False
                        break
                if not valid: break
        if valid:
            ans = max(ans, bin(mask).count('1'))
    return ans

